fn valid_char(c: Str) -> Bool {
  return c == "." or c == "1" or c == "2" or c == "3" or c == "4" or c == "5" or c == "6" or c == "7" or c == "8" or c == "9"
}

fn cell(rows: List[Str], r: Int, c: Int) -> Str {
  return rows.get_or(r, "").chars().get_or(c, ".")
}

fn column(rows: List[Str], c: Int) -> List[Str] {
  return range(0, 9).map(fn(r) => cell(rows: rows, r: r, c: c))
}

fn box_cells(rows: List[Str], b: Int) -> List[Str] {
  let r0 = (b / 3) * 3
  let c0 = (b % 3) * 3
  return range(0, 9).map(fn(k) => cell(rows: rows, r: r0 + k / 3, c: c0 + k % 3))
}

fn unit_ok(vals: List[Str]) -> Bool {
  let filled = vals.filter(fn(x) => x != ".")
  return filled.unique().len() == filled.len()
}

pub fn sudoku(rows: List[Str]) -> Bool {
  if rows.len() != 9 {
    return false
  }
  for row in rows {
    if row.len() != 9 {
      return false
    }
    for ch in row.chars() {
      if not (valid_char(ch)) {
        return false
      }
    }
  }
  for i in range(0, 9) {
    if not (unit_ok(rows.get_or(i, "").chars())) {
      return false
    }
    if not (unit_ok(column(rows: rows, c: i))) {
      return false
    }
    if not (unit_ok(box_cells(rows: rows, b: i))) {
      return false
    }
  }
  return true
}
